WITH first_sale AS (SELECT seller_id, MIN(order_purchase_timestamp)::date AS first_sale_date FROM facts.fct_order_item i INNER JOIN staging.orders o USING(order_id) GROUP BY seller_id), closed AS (SELECT seller_id, won_date FROM facts.fct_seller_funnel WHERE seller_id IS NOT NULL GROUP BY 1,2) SELECT c.seller_id, c.won_date, f.first_sale_date, f.first_sale_date-c.won_date AS days_to_first_sale, CASE WHEN f.first_sale_date BETWEEN c.won_date AND c.won_date+INTERVAL '30 days' THEN '0-30d' WHEN f.first_sale_date BETWEEN c.won_date+INTERVAL '31 days' AND c.won_date+INTERVAL '90 days' THEN '31-90d' ELSE 'after_90d_or_unmatched' END AS activation_bucket FROM closed c LEFT JOIN first_sale f USING(seller_id);

